  3	}
  4	
  5	export interface Item {
  6	  type: string;
  7	  material?: string;
  8	  enchantment?: number;
  9	  cursed?: boolean;
 10	}
 11	
 12	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
 13	  sword: 100,
 14	  amulet: 60,
 15	  staff: 80,
 16	  potion: 40,
 17	};
 18	
 19	// Components (e.g. runes, moonstones) are not individually price-listed: they all
 20	// share one tariff, so the component roster is the single source of which types
 21	// are components and what each of them costs.
 22	const COMPONENT_TYPES = ["rune", "moonstone"];
 23	const COMPONENT_BASE_PREMIUM = 25;
 24	
 25	const BASE_PREMIUMS: Record<string, number> = {
 26	  ...MAIN_ITEM_BASE_PREMIUMS,
 27	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_BASE_PREMIUM])),
 28	};
 29	
 30	const BLOCK_SIZE = 3;
 31	const BLOCK_BASE_PREMIUM = 60;
 32	
 33	// MHPCO reading of "alike": two items are alike exactly when their types match,
 34	// not merely when they belong to the same family (rune-y, gemstone-y).
 35	function countAlikeItems(items: Item[]): Map<string, number> {
 36	  const counts = new Map<string, number>();
 37	  for (const item of items) {
 38	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
 39	  }
 40	  return counts;
 41	}
 42	
 43	// A building block is offered for exactly 3 alike components.
 44	function blockOfferApplies(type: string, count: number): boolean {
 45	  return COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE;
 46	}
 47	
 48	// What the MHPCO is willing to insure at all: only item types on its price list. The
 49	// acceptance rule is enforced at the lookup every price enquiry must pass through, so no
 50	// part of a declined cover can be priced by any route.
 51	function listedBasePremium(type: string): number {
 52	  const basePremium = BASE_PREMIUMS[type];
 53	  if (basePremium === undefined) {
 54	    throw new Error(`MHPCO does not insure items of type "${type}"`);
 55	  }
 56	  return basePremium;
 57	}
 58	
 59	function typeBasePremium(type: string, count: number): number {
 60	  if (blockOfferApplies(type, count)) {
 61	    return BLOCK_BASE_PREMIUM;
 62	  }
 63	  return count * listedBasePremium(type);
 64	}
 65	
 66	function policyBasePremium(items: Item[]): number {
 67	  let total = 0;
 68	  for (const [type, count] of countAlikeItems(items)) {
 69	    total += typeBasePremium(type, count);
 70	  }
 71	  return total;
 72	}
 73	
 74	const CURSE_SURCHARGE = 0.5;
 75	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
 76	const SURCHARGED_ENCHANTMENT_LEVEL = 5;
 77	
 78	// The enchantment level from which the MHPCO rates an item as a heightened risk worth a
 79	// premium surcharge. Deliberately a lower bar than the level at which the claim side
 80	// halves a reimbursement: charging more for enchantment and paying out less for it are
 81	// two clauses with their own thresholds, and neither follows the other when it moves.
 82	function isEnchantedEnoughToSurcharge(item: Item): boolean {
 83	  return (item.enchantment ?? 0) >= SURCHARGED_ENCHANTMENT_LEVEL;
 84	}
 85	
 86	// Each risk factor the MHPCO recognises contributes its own rate; a cursed and
 87	// highly enchanted item is assessed both surcharges.
 88	function riskSurchargeRate(item: Item): number {
 89	  return (
 90	    (item.cursed === true ? CURSE_SURCHARGE : 0) +
 91	    (isEnchantedEnoughToSurcharge(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0)
 92	  );
 93	}
 94	
 95	// Item-scoped risk surcharges are assessed against the affected item's own listed
 96	// base premium -- the block offer discounts the policy base premium only and does not
 97	// lower the surcharge base. Each item is rated separately and the results are summed.
 98	function itemScopedSurcharges(items: Item[]): number {
 99	  return items.reduce(
100	    (total, item) => total + listedBasePremium(item.type) * riskSurchargeRate(item),
101	    0,
102	  );
103	}
104	
105	const FIRST_INSURANCE_SURCHARGE = 0.1;
106	const LOYALTY_DISCOUNT = 0.2;
107	const LOYALTY_YEARS = 2;
108	
109	// Long-standing means at least LOYALTY_YEARS years of business. A discount, so it
110	// enters the policy-scoped rate as a negative rate.
111	function loyaltyRate(customer: Customer): number {
112	  return customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT : 0;
113	}
114	
115	const FOLLOW_UP_DISCOUNT = 0.15;
116	
117	// Every contract after the customer's first earns the follow-up discount.
118	function followUpRate(previousContracts: number): number {
119	  return previousContracts > 0 ? -FOLLOW_UP_DISCOUNT : 0;
120	}
121	
122	// The MHPCO's policy-scoped tariff: each recognised policy-wide modifier contributes
123	// its own rate, and the rates are assessed together against the policy base premium.
124	//
125	// MHPCO reading of "a first insurance": the initial assessment is of the items newly
126	// brought in, not of the customer. Every quote is therefore a first insurance for the
127	// items it covers, so the surcharge is an unconditional term here -- it consults no
128	// customer history, and a long-standing customer on a follow-up contract is assessed
129	// it alongside the loyalty and follow-up discounts rather than instead of them.
130	function policyScopedRate(customer: Customer, previousContracts: number): number {
131	  return FIRST_INSURANCE_SURCHARGE + loyaltyRate(customer) + followUpRate(previousContracts);
132	}
133	
134	// Policy-scoped modifiers are assessed against the policy base premium alone -- the
135	// plain sum of the item base premiums, deliberately excluding item-scoped surcharges.
136	function policyScopedAdjustment(
137	  basePremium: number,
138	  customer: Customer,
139	  previousContracts: number,
140	): number {
141	  return basePremium * policyScopedRate(customer, previousContracts);
142	}
143	
144	const PROCESSING_FEE = 5;
145	
146	// Amounts are rounded in the MHPCO's favor, which means opposite directions on the two
147	// sides of the ledger: a premium the MHPCO collects rounds up, a payout it owes rounds
148	// down. Both tolerate the same floating-point slack so that an amount computed as
149	// exactly 197.5 or 350.5 is not pushed across the boundary by representation error.
150	const AMOUNT_PRECISION = 1e-9;
151	
152	function roundUpInMHPCOFavor(amount: number): number {
153	  return Math.ceil(amount - AMOUNT_PRECISION);
154	}
155	
156	// How the MHPCO closes a premium: the processing fee is added at the very end, after
157	// every percentage modifier, and only that final figure is rounded -- intermediate
158	// amounts stay fractional, and rounding always favours the MHPCO.
159	function closedPremium(modifiedPremium: number): number {
160	  return roundUpInMHPCOFavor(modifiedPremium + PROCESSING_FEE);
161	}
162	
163	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
164	  const basePremium = policyBasePremium(items);
165	  return closedPremium(
166	    basePremium +
167	      itemScopedSurcharges(items) +
168	      policyScopedAdjustment(basePremium, customer, previousContracts),
169	  );
170	}
171	
172	export interface Damage {
173	  itemType: string;
174	  amount: number;
175	}
176	
177	export interface Incident {
178	  cause: string;
179	  damages: Damage[];
180	}
181	
182	export interface ClaimSettlement {
183	  payout: number;
184	  remainingCap: number;
185	}
186	
187	const DEDUCTIBLE = 100;
188	
189	function roundDownInMHPCOFavor(amount: number): number {
190	  return Math.floor(amount + AMOUNT_PRECISION);
191	}
192	
193	const HALVED_ENCHANTMENT_LEVEL = 8;
194	const HALVED_REIMBURSEMENT = 0.5;
195	
196	// Which insured items the MHPCO considers too enchanted to reimburse in full. An item
197	// with no enchantment level at all is not enchanted and so never triggers the clause.
198	function isEnchantedEnoughToHalve(insured: Item): boolean {
199	  return (insured.enchantment ?? 0) >= HALVED_ENCHANTMENT_LEVEL;
200	}
201	
202	// How much of a reported damage the MHPCO recognises before the deductible: a special
203	// clause can reduce the recognised amount, and absent any clause the full damage counts.
204	function reimbursableDamage(damage: Damage, insured: Item): number {
205	  if (isEnchantedEnoughToHalve(insured)) {
206	    return damage.amount * HALVED_REIMBURSEMENT;
207	  }
208	  return damage.amount;
209	}
210	
211	// Each damage event bears its own deductible, and the MHPCO never pays less than nothing.
212	function reimbursement(damage: Damage, insured: Item): number {
213	  return Math.max(reimbursableDamage(damage, insured) - DEDUCTIBLE, 0);
214	}
215	
216	// What the MHPCO owes for an incident: every damage in it is reimbursed on its own terms
217	// and the reimbursements are added up. One incident can damage several insured items, and
218	// the deductible bites per damage rather than per incident.
219	function incidentReimbursement(damages: Damage[], items: Item[]): number {
220	  return damages.reduce((total, damage) => {
221	    const insured = items.find((item) => item.type === damage.itemType) as Item;
222	    return total + reimbursement(damage, insured);
223	  }, 0);
224	}
225	
226	export function claim(items: Item[], incident: Incident): ClaimSettlement {
227	  // remainingCap is a provisional 0: the insurance sum and the twice-the-sum cap are not
228	  // behaviors of this module yet, so no cap has been assessed to report a remainder of.
229	  return {
230	    payout: roundDownInMHPCOFavor(incidentReimbursement(incident.damages, items)),
231	    remainingCap: 0,
232	  };
233	}

